static juce::String coldChunkHash(juce::ValueTree node){auto chunk=node.getProperty("state").toString();return juce::SHA256(chunk.toRawUTF8(),size_t(chunk.getNumBytesAsUTF8())).toHexString();}
static void coldAddNote(Session& s){auto* track=te::getAudioTracks(*s.edit)[0];auto clip=track->insertMIDIClip("Cold note",{Session::time(0),Session::time(48000)},nullptr);require(clip!=nullptr,"Cold MIDI clip failed");s.edit->tempoSequence.getTempo(0)->setBpm(120);clip->getSequence().addNote(60,tracktion::BeatPosition::fromBeats(0.5),tracktion::BeatDuration::fromBeats(0.5),127,0,nullptr);}
