 if(expectedError.isNotEmpty()){
  s.addTrack()->setName("Unsaved current edit");auto* current=s.edit.get();auto currentFile=s.projectFile;auto before=s.edit->state.toXmlString();bool rejected=false;
  try{s.openProject(project);}catch(const std::exception& e){rejected=juce::String::fromUTF8(e.what()).contains(expectedError);}
  require(rejected&&s.edit.get()==current&&s.projectFile==currentFile&&s.edit->state.toXmlString()==before&&known.getTypes().isEmpty(),"Invalid catalog changed current edit or registry");
 }else{
  if(bool(request["template"])){s.loadTemplate(project,scanTimeout);require(s.clips().isEmpty(),"Cold template retained media");if(bool(request["midi"]))coldAddNote(s);else s.importAudio(juce::File(request["source"].toString()),0,0);}else s.openProject(project,scanTimeout);
  require(known.getTypes().size()==int(request["registered"]),"Cold catalog registered unexpected plugins");
  auto inspect=[&]{int total=0;missing=0;for(auto node:Session::referencedPluginStates(s.edit->state)){++total;bool found=false;for(auto expected:*request["chunks"].getArray())if(node.getProperty("id").toString()==expected["id"].toString()){require(coldChunkHash(node)==expected["sha256"].toString(),"Cold opaque plugin state differs");found=true;}require(found,"Cold plugin instance identity differs");}
   require(total==request["chunks"].getArray()->size(),"Cold plugin count differs");
   for(auto* track:te::getAudioTracks(*s.edit))for(auto* p:track->pluginList.getPluginsOfType<te::ExternalPlugin>()){p->initialiseFully();if(!p->getAudioPluginInstance())++missing;else if(bool(request["midi"]))require(p->desc.isInstrument,"Cold instrument metadata lost");}
   for(auto* p:s.edit->getMasterPluginList().getPluginsOfType<te::ExternalPlugin>()){p->initialiseFully();if(!p->getAudioPluginInstance())++missing;}
   require(missing==int(request["missing"]),"Cold plugin availability differs");
  };inspect();
  if(bool(request["frozen"]))require(s.trackAt(0).isFrozen(te::Track::individualFreeze),"Cold project lost freeze");
  auto output=s.root.getChildFile("cold.wav");if(missing){bool rejected=false;try{s.render(output);}catch(const std::exception&){rejected=true;}require(rejected&&!output.exists(),"Cold missing plugin rendered incomplete audio");}
  else{s.render(output);auto audio=readWave(output);require(std::abs(audio.getSample(0,int(request["sample"])))>0,"Cold output silent");require(std::abs(audio.getSample(0,int(request["sample"]))-float(request["expected"]))<1e-7f,"Cold rendered audio differs");auto reference=readWave(juce::File(request["reference"].toString()));require(reference.getMagnitude(0,48000)>1e-5f,"Cold reference silent");for(int c=0;c<2;++c)for(int i=0;i<48000;++i)audioError=std::max(audioError,std::abs(audio.getSample(c,i)-reference.getSample(c,i)));require(audioError<1e-7f,"Cold full stereo render differs");audioCompared=true;}
  auto saved=s.root.getChildFile("roundtrip.tracktionedit");s.saveAs(saved);s.openProject(saved,scanTimeout);inspect();
 }
 if(bool(request["forbid_fault_factory"]))require(!s.root.getChildFile("temp/native-scan-entered-1.txt").existsAsFile(),"Unreferenced catalog binary executed");require(s.engine.getDeviceManager().deviceManager.getCurrentAudioDevice()==nullptr,"Cold worker opened physical device");
 juce::Array<juce::var> scanStatuses;for(auto folder:s.root.findChildFiles(juce::File::findDirectories,false,"legacy-scan-*")){auto status=juce::JSON::parse(folder.getChildFile("scan-status.json"));auto expected=request["expected_scan_status"].toString();if(expected.isNotEmpty())require(status["status"].toString()==expected,"Legacy targeted scan status differs");if(expected=="failed")require(int(status["exit_code"])==73,"Legacy native failure code differs");scanStatuses.add(status["status"]);}
 if(request["expected_scan_status"].toString().isNotEmpty())require(scanStatuses.size()==1,"Legacy scan was repeated or skipped unexpectedly");
 auto* result=new juce::DynamicObject;result->setProperty("full_audio_compared",audioCompared);result->setProperty("full_audio_max_error",audioError);result->setProperty("legacy_scan_statuses",scanStatuses);result->setProperty("empty_registry_at_start",true);result->setProperty("registered",known.getTypes().size());result->setProperty("missing",missing);result->setProperty("rejected_unchanged",expectedError.isNotEmpty());result->setProperty("physical_device_opened",false);s.root.getChildFile("cold-result.json").replaceWithText(juce::JSON::toString(juce::var(result)));
